static void CosmicMessage(const FString& Text, const FColor& Color, float Seconds = 8.f)
{
	if (GEngine) GEngine->AddOnScreenDebugMessage(-1, Seconds, Color, Text);
	UE_LOG(LogTemp, Log, TEXT("[Cosmic] %s"), *Text);
}

FDukeAestheticProfile FDukeAestheticProfile::Inherit(const FDukeAestheticProfile& A, const FDukeAestheticProfile& B)
{
	FDukeAestheticProfile C;
	C.PreferredClothingTint = (A.PreferredClothingTint + B.PreferredClothingTint) * 0.5f;
	C.PreferredClothingTint.R = FMath::Clamp(C.PreferredClothingTint.R + FMath::FRandRange(-0.04f, 0.04f), 0.f, 1.f);   // style drift
	C.PreferredClothingTint.G = FMath::Clamp(C.PreferredClothingTint.G + FMath::FRandRange(-0.04f, 0.04f), 0.f, 1.f);
	C.PreferredClothingTint.B = FMath::Clamp(C.PreferredClothingTint.B + FMath::FRandRange(-0.04f, 0.04f), 0.f, 1.f);
	C.ArmorPlatingDensityPreference = FMath::Clamp((A.ArmorPlatingDensityPreference + B.ArmorPlatingDensityPreference) * 0.5f + FMath::FRandRange(-0.05f, 0.05f), 0.f, 1.f);
	C.CulturalArchitecturePrefix = FMath::RandBool() ? A.CulturalArchitecturePrefix : B.CulturalArchitecturePrefix;
	return C;
}

// ---------------- planets and property ----------------
ADukeSovereignPlanet::ADukeSovereignPlanet() { PrimaryActorTick.bCanEverTick = false; }
void ADukeSovereignPlanet::BeginPlay()
{
	Super::BeginPlay();
	if (UDukeCosmicDirector* D = GetWorld()->GetSubsystem<UDukeCosmicDirector>()) D->Planets.AddUnique(this);
}
int32 ADukeSovereignPlanet::ListProperty(const FString& Address, float Value, AActor* Owner)
{
	FDukeRealEstateDeed D; D.PropertyAddress = Address; D.PurchaseValue = D.CurrentAppraisedValue = Value; D.Owner = Owner;
	return PropertyLedger.Add(D);
}
bool ADukeSovereignPlanet::BuyProperty(int32 I, AActor* Buyer, float& BuyerCredits)
{
	if (!PropertyLedger.IsValidIndex(I) || !Buyer) return false;
	FDukeRealEstateDeed& D = PropertyLedger[I];
	if (BuyerCredits < D.CurrentAppraisedValue || D.Owner.Get() == Buyer) return false;
	BuyerCredits -= D.CurrentAppraisedValue;
	if (ADukeSmartNPC* Seller = Cast<ADukeSmartNPC>(D.Owner.Get())) Seller->AccumulatedCredits += D.CurrentAppraisedValue;
	D.PurchaseValue = D.CurrentAppraisedValue; D.Owner = Buyer;
	return true;
}
bool ADukeSovereignPlanet::RentProperty(int32 I, AActor* Tenant, float MonthlyRent)
{
	if (!PropertyLedger.IsValidIndex(I) || PropertyLedger[I].bIsCurrentlyRented) return false;
	FDukeRealEstateDeed& D = PropertyLedger[I]; D.bIsCurrentlyRented = true; D.Tenant = Tenant; D.MonthlyRentRate = MonthlyRent;
	return true;
}
void ADukeSovereignPlanet::CollectRentAndAppreciate()
{
	// a raid depresses the market, a boom lifts it
	const float Mood = EventState == EDukeCosmicEvent::UnderRaiderAttack ? -0.03f : (GlobalEconomicLiquidity > CityFoundingThreshold * 0.8f ? MarketGrowthPerHeartbeat * 1.5f : MarketGrowthPerHeartbeat);
	for (FDukeRealEstateDeed& D : PropertyLedger)
	{
		D.CurrentAppraisedValue = FMath::Max(100.f, D.CurrentAppraisedValue * (1.f + Mood + FMath::FRandRange(-0.005f, 0.005f)));
		if (!D.bIsCurrentlyRented) continue;
		ADukeSmartNPC* Tenant = Cast<ADukeSmartNPC>(D.Tenant.Get()); ADukeSmartNPC* Landlord = Cast<ADukeSmartNPC>(D.Owner.Get());
		if (Tenant && Tenant->AccumulatedCredits >= D.MonthlyRentRate)
		{
			Tenant->AccumulatedCredits -= D.MonthlyRentRate;
			if (Landlord) Landlord->AccumulatedCredits += D.MonthlyRentRate;
			GlobalEconomicLiquidity += D.MonthlyRentRate * 0.1f;   // money moving grows the economy
		}
		else { D.bIsCurrentlyRented = false; D.Tenant = nullptr; }   // eviction
	}
}

// ---------------- the cosmic director ----------------
void UDukeCosmicDirector::Tick(float DeltaTime)
{
	const float Now = GetWorld() ? GetWorld()->GetTimeSeconds() : 0.f;
	for (auto It = RaidEndsAt.CreateIterator(); It; ++It)
		if (Now >= It.Value()) { if (ADukeSovereignPlanet* P = It.Key().Get()) ClearRaiderAttackAndStartCeremonies(P); It.RemoveCurrent(); }
	for (auto It = MourningEndsAt.CreateIterator(); It; ++It)
		if (Now >= It.Value()) { if (ADukeSovereignPlanet* P = It.Key().Get()) P->EventState = EDukeCosmicEvent::ExtremeArmedVigilance; It.RemoveCurrent(); }
	Timer += DeltaTime;
	if (Timer < HeartbeatSeconds) return;
	Timer = 0.f;
	Heartbeat();
}
void UDukeCosmicDirector::Heartbeat()
{
	ProcessMacroDevelopment();
	EvaluateRaiderIncursions();
	ProcessGenerations();
	ProcessTyranny();
}
// a notorious player (many citizen killings) makes ordinary people near them flee or arm themselves
void UDukeCosmicDirector::ProcessTyranny()
{
	for (TActorIterator<ADukeJediPlayer> It(GetWorld()); It; ++It)
	{
		if (It->Notoriety < TyrantNotoriety) continue;
		int32 Fled = 0;
		for (ADukeSmartNPC* N : Population)
			if (N && FVector::DistSquared(N->GetActorLocation(), It->GetActorLocation()) < FMath::Square(TyrantFearRadius) && N->ReactToTyranny(*It)) ++Fled;
		if (Fled) CosmicMessage(FString::Printf(TEXT("%d citizens flee from you in fear."), Fled), FColor::Yellow);
	}
}
// booming economies push their boundaries out: the NPCs found a new city
void UDukeCosmicDirector::ProcessMacroDevelopment()
{
	for (ADukeSovereignPlanet* P : Planets)
	{
		if (!P) continue;
		P->CollectRentAndAppreciate();
		if (P->GlobalEconomicLiquidity > P->CityFoundingThreshold && P->EventState != EDukeCosmicEvent::UnderRaiderAttack)
		{
			const FString Name = FDukeTatooineNames::NewSettlementName(CityCounter++);
			P->ActiveCities.Add(Name); P->GlobalEconomicLiquidity -= P->CityFoundingCost;
			if (UDukeGalaxyDirector* G = GetWorld()->GetSubsystem<UDukeGalaxyDirector>())
				G->GenerateSettlement(P->GetActorLocation() + FVector(FMath::RandRange(-20000.f, 20000.f), FMath::RandRange(-20000.f, 20000.f), 0.f));
			CosmicMessage(FString::Printf(TEXT("EXPANSION: the people of %s have founded a new city: %s"), *P->PlanetName, *Name), FColor::Orange, 10.f);
		}
	}
}
void UDukeCosmicDirector::EvaluateRaiderIncursions()
{
	const float Now = GetWorld()->GetTimeSeconds();
	for (ADukeSovereignPlanet* P : Planets)
	{
		if (!P || P->Biome != EDukePlanetBiome::Desert) continue;   // Tusken raiders: desert worlds
		if (P->EventState != EDukeCosmicEvent::NormalHustleAndBustle && P->EventState != EDukeCosmicEvent::ExtremeArmedVigilance) continue;
		const float Chance = P->EventState == EDukeCosmicEvent::ExtremeArmedVigilance ? RaidChance * 0.5f : RaidChance;   // an armed town deters raids
		if (FMath::FRand() > Chance)
		{
			if (P->EventState == EDukeCosmicEvent::ExtremeArmedVigilance)   // a quiet year: the town stands down
			{
				P->EventState = EDukeCosmicEvent::NormalHustleAndBustle;
				for (ADukeSmartNPC* N : Population)
					if (N && N->CurrentResidencePlanet == P && N->CurrentState == EDukeNpcState::CombatDuty && !N->bIsRecruited) N->CurrentState = EDukeNpcState::Working;
			}
			continue;
		}
		P->EventState = EDukeCosmicEvent::UnderRaiderAttack; RaidEndsAt.Add(P, Now + RaidDurationSeconds);
		CosmicMessage(FString::Printf(TEXT("TUSKEN RAIDERS on %s! Smoke on the horizon."), *P->PlanetName), FColor::Red, 12.f);
		SpawnSmokePlumes(P);
		for (ADukeSmartNPC* N : Population)
			if (N && N->CurrentState != EDukeNpcState::Dead && N->CurrentResidencePlanet == P) N->CurrentState = EDukeNpcState::CombatDuty;
	}
}
void UDukeCosmicDirector::ClearRaiderAttackAndStartCeremonies(ADukeSovereignPlanet* P)
{
	if (!P) return;
	P->EventState = EDukeCosmicEvent::MourningCeremony;
	MourningEndsAt.Add(P, GetWorld()->GetTimeSeconds() + 90.f);
	CosmicMessage(FString::Printf(TEXT("%s: the raid is over. The town gathers for the burial burnings; weapons stay in hand."), *P->PlanetName), FColor::Orange, 10.f);
	for (ADukeSmartNPC* N : Population)
		if (N && N->CurrentState != EDukeNpcState::Dead && N->CurrentResidencePlanet == P) N->CurrentState = EDukeNpcState::CombatDuty;   // armed vigilance
}
void UDukeCosmicDirector::SpawnSmokePlumes(ADukeSovereignPlanet* P)
{
	if (!SmokePlumeClass || !P) return;
	for (int32 i = 0; i < 3; ++i)
		GetWorld()->SpawnActor<AActor>(SmokePlumeClass, P->GetActorLocation() + FVector(FMath::RandRange(-15000.f, 15000.f), FMath::RandRange(-15000.f, 15000.f), 0.f), FRotator::ZeroRotator);
}
// age, sickness and death with inheritance; couples have children who inherit and blend their style
void UDukeCosmicDirector::ProcessGenerations()
{
	TArray<ADukeSmartNPC*> Alive;
	for (ADukeSmartNPC* N : Population) if (N && N->CurrentState != EDukeNpcState::Dead) Alive.Add(N);
	for (ADukeSmartNPC* N : Alive) N->ProcessSicknessAndGenerationalPassing();
	for (ADukeSmartNPC* N : Alive)
		if (N && N->CurrentState != EDukeNpcState::Dead && N->Family.Spouse && N->AgeInTicks >= 20 && N->AgeInTicks <= 45 && N->ChildrenReferences.Num() < 4 && FMath::FRand() < 0.04f)
			N->ProcreateAndPassAestheticStyle(N->Family.Spouse);
}
